USE DHW_DATABASE;
GO

IF OBJECT_ID('dbo.GOODSCLASSIFICATION', 'U') IS NOT NULL DROP TABLE dbo.GOODSCLASSIFICATION;
GO

CREATE TABLE dbo.GOODSCLASSIFICATION (
    citemno      VARCHAR(10)    NULL,
    cdescrip     VARCHAR(100)   NULL,
    ccommodity   VARCHAR(50)    NULL,
    chtcode      VARCHAR(15)    NULL,
    nvolume      DECIMAL(10,4)  NULL,
    nbtlcontent  DECIMAL(10,4)  NULL,
    ncaseqty     DECIMAL(10,2)  NULL,
    ntarrif01    DECIMAL(10,4)  NULL,
    ntarrif02    DECIMAL(10,4)  NULL,
    ntarrif03    DECIMAL(10,4)  NULL,
    ntarrif04    DECIMAL(10,4)  NULL,
    ntarrif05    DECIMAL(10,4)  NULL,
    ntarrif06    DECIMAL(10,4)  NULL
);
GO

